#!/usr/bin/env php
<?php
declare(strict_types=1);

final class M8InsightBreadthAcceptance {
    private const API='/wp-json/research-manager/v1';
    private const SCOPES=['site.read','site.diagnostics','insights.write','translations.write','research.read','operations.apply','operations.rollback'];
    private const SLICES=['update','relation','pair','schedule','status'];
    private string $base,$token,$slice,$evidencePath; private bool $apply; private array $evidence=[], $rollbacks=[];
    public function __construct(array $argv){
        $this->base=rtrim((string)getenv('ERM_BASE_URL'),'/'); $this->token=trim((string)getenv('ERM_TOKEN'));
        $this->apply=in_array('--apply',$argv,true); $this->slice=$this->arg($argv,'--slice=');
        $this->evidencePath=$this->arg($argv,'--evidence=') ?: 'tmp/final-v1-insight-'.$this->slice.'-'.gmdate('Ymd\\THis\\Z').'-'.getmypid().'.json';
    }
    public function run(): int {
        try {
            $this->validate(); $this->evidence=['schema_version'=>1,'milestone'=>'M8','slice'=>'final-v1-insight-editorial-breadth','editorial_slice'=>$this->slice,'site'=>$this->base,'apply_enabled'=>$this->apply,'expected_scopes'=>self::SCOPES,'requests'=>[],'checks'=>[],'started_at'=>gmdate(DATE_ATOM),'result'=>'running'];
            $this->preflight();
            if(!$this->apply){$this->evidence['apply_skipped']=true; return $this->finish(true,'M8 Insight '.$this->slice." preflight: PASS\nNo production mutation was executed.");}
            match($this->slice){'update'=>$this->update(),'relation'=>$this->relation(),'pair'=>$this->pair(),'schedule'=>$this->schedule(),'status'=>$this->status()};
            $this->check('no-pending-rollbacks',!array_filter($this->rollbacks,fn($r)=>!$r['done']),['rollbacks'=>$this->rollbacks]);
            return $this->finish(true,'M8 Insight '.$this->slice." reversible production acceptance: PASS\nTemporary fixtures removed; bounded baseline restored.");
        } catch(Throwable $e){$this->emergency(); $this->evidence['failure']=['class'=>get_class($e),'message'=>$e->getMessage()]; return $this->finish(false,'M8 Insight '.$this->slice.' acceptance: FAIL — '.$e->getMessage());}
    }
    private function preflight(): void {
        $cap=$this->data($this->req('GET','/capabilities',null,[200],'capabilities')); $got=array_values((array)($cap['granted_scopes']??[])); sort($got); $exp=self::SCOPES; sort($exp); $this->check('exact-scope-profile',$got===$exp,['got'=>$got,'expected'=>$exp]);
        $supported=(array)($cap['mutation_transport']['supported_operations']??[]); $this->check('insight-create-update-supported',in_array('insight-create',$supported,true)&&in_array('insight-update',$supported,true),['supported'=>$supported]);
        $ctl=(array)($cap['insight_control']??[]); $fields=(array)($ctl['update_fields']??[]); foreach(['title','excerpt','content','insight_type'] as $f)$this->check('update-field-'.$f,in_array($f,$fields,true),['fields'=>$fields]);
        if($this->slice==='pair'){ $p=(array)($ctl['translation_pairing']??[]); $this->check('pairing-capability',!empty($p['available'])&&in_array('insight-pair',(array)($p['operations']??[]),true),['pairing'=>$p]); }
        if($this->slice==='schedule'){ $s=(array)($ctl['scheduling']??[]); $this->check('scheduling-capability',!empty($s['available'])&&($s['field']??'')==='scheduled_at'&&!empty($s['future_only']),['scheduling'=>$s]); }
        if($this->slice==='status'){ $s=(array)($ctl['status_transition']??[]); $a=(array)($s['allowed']??[]); $this->check('status-capability',!empty($s['available'])&&in_array('draft',$a,true)&&in_array('publish',$a,true),['status'=>$s]); }
        if($this->slice==='relation'){ $r=(array)($ctl['research_relations']??[]); $this->check('relations-capability',!empty($r['available'])&&($r['field']??'')==='line_ids',['relations'=>$r]); $line=$this->line(); if(!$line)throw new RuntimeException('No existing verified active English Research Line is available for a safe relation fixture. Leave relation open until M5 creates a reversible temporary Line.'); $this->evidence['selected_relation_fixture']=$line; }
    }
    private function update(): void {
        $f=$this->fixture('en','draft','Update'); $before=$this->inspect($f['id'],'update-before');
        $changes=['title'=>'Temporary M8 editorial update — reversible production proof','excerpt'=>'Temporary reversible excerpt used only for final v1 editorial breadth acceptance.','content'=>'<p>Temporary reversible content used only for final v1 editorial breadth acceptance.</p>','insight_type'=>'explainer'];
        $p=$this->plan('insight-update',['post_id'=>$f['id'],'changes'=>$changes,'reason'=>'Final v1 Insight update breadth'],'update-plan'); $this->check('update-preview-no-mutation',$this->state($before)===$this->state($this->inspect($f['id'],'update-preview')),[]);
        $op=$this->apply($p,'update-apply'); $this->verify($op,true,'update-verify'); $after=$this->inspect($f['id'],'update-after');
        $this->check('update-applied',($after['title']??'')===$changes['title']&&($after['excerpt']??'')===$changes['excerpt']&&str_contains((string)($after['content']??''),'Temporary reversible content')&&($after['insight_type']??'')==='explainer',['after'=>$this->state($after)]);
        $this->rollback($op,'update-rollback'); $this->check('update-baseline-restored',$this->state($before)===$this->state($this->inspect($f['id'],'update-restored')),[]); $this->cleanup($f,'update-fixture-cleanup');
    }
    private function relation(): void {
        $line=(array)($this->evidence['selected_relation_fixture']??[]); $lid=(int)($line['post_id']??0); $f=$this->fixture('en','draft','Relation'); $before=$this->inspect($f['id'],'relation-before'); $this->check('relation-baseline-empty',[]===array_values(array_map('intval',(array)($before['line_ids']??[]))),[]);
        $p=$this->plan('insight-update',['post_id'=>$f['id'],'changes'=>['line_ids'=>[$lid]],'reason'=>'Final v1 Insight relation breadth'],'relation-plan'); $this->check('relation-preview-no-mutation',[]===array_values(array_map('intval',(array)($this->inspect($f['id'],'relation-preview')['line_ids']??[]))),[]);
        $op=$this->apply($p,'relation-apply'); $this->verify($op,true,'relation-verify'); $after=$this->inspect($f['id'],'relation-after'); $this->check('relation-applied',[$lid]===array_values(array_map('intval',(array)($after['line_ids']??[]))),['after'=>$after['line_ids']??[]]);
        $seo=$this->data($this->req('GET','/insights/'.$f['id'].'/seo-geo',null,[200],'relation-seo-geo')); $rel=(array)($seo['relations']??[]); $this->check('relation-diagnostics',(int)($rel['count']??0)===1&&!empty($rel['verified_same_language']),['relations'=>$rel]);
        $this->rollback($op,'relation-rollback'); $this->check('relation-baseline-restored',[]===array_values(array_map('intval',(array)($this->inspect($f['id'],'relation-restored')['line_ids']??[]))),[]); $this->cleanup($f,'relation-fixture-cleanup');
    }
    private function pair(): void {
        $en=$this->fixture('en','draft','Pair EN'); $es=$this->fixture('es','draft','Pair ES');
        $plan=$this->data($this->req('POST','/insights/pairing/plan',['operation'=>'insight-pair','payload'=>['first_id'=>$en['id'],'second_id'=>$es['id']]],[200],'pair-plan')); $pid=(string)($plan['plan_id']??''); $this->id($pid,'pair plan_id'); $this->check('pair-preview-allowed',!empty($plan['apply_allowed']),['plan'=>$plan]);
        $a=$this->data($this->req('POST','/insights/pairing/plans/'.rawurlencode($pid).'/apply',['confirm'=>true],[200],'pair-apply')); $op=(string)($a['operation_id']??''); $this->id($op,'pair operation_id'); $this->track($op,'/insights/pairing/operations/'.rawurlencode($op).'/rollback');
        $v=$this->data($this->req('POST','/insights/pairing/operations/'.rawurlencode($op).'/verify',['rendered'=>false],[200],'pair-verify')); $this->check('pair-stored-verified',!empty($v['stored_verification']['verified']),['verify'=>$v]);
        $this->rollback($op,'pair-rollback'); $r=$this->data($this->req('POST','/insights/pairing/plan',['operation'=>'insight-pair','payload'=>['first_id'=>$en['id'],'second_id'=>$es['id']]],[200],'pair-restored-replan')); $this->check('pair-baseline-restored',!empty($r['apply_allowed'])&&!empty($r['plan_id']),['replan'=>$r]);
        $this->cleanup($es,'pair-es-cleanup'); $this->cleanup($en,'pair-en-cleanup');
    }
    private function schedule(): void {
        $f=$this->fixture('en','draft','Schedule'); $before=$this->inspect($f['id'],'schedule-before'); $at=gmdate('Y-m-d\\TH:i:s\\Z',time()+3600);
        $p=$this->plan('insight-update',['post_id'=>$f['id'],'changes'=>['scheduled_at'=>$at],'reason'=>'Final v1 Insight scheduling breadth'],'schedule-plan'); $preview=$this->inspect($f['id'],'schedule-preview'); $this->check('schedule-preview-no-mutation',($preview['status']??'')===($before['status']??'')&&(string)($preview['scheduled_at']??'')===(string)($before['scheduled_at']??''),[]);
        $op=$this->apply($p,'schedule-apply'); $this->verify($op,true,'schedule-verify'); $after=$this->inspect($f['id'],'schedule-after'); $this->check('schedule-applied',($after['status']??'')==='future'&&($after['scheduled_at']??'')===$at,['after'=>$this->state($after)]);
        $this->rollback($op,'schedule-rollback'); $rest=$this->inspect($f['id'],'schedule-restored'); $this->check('schedule-baseline-restored',($rest['status']??'')==='draft'&&(string)($rest['scheduled_at']??'')==='',[]); $this->cleanup($f,'schedule-fixture-cleanup');
    }
    private function status(): void {
        $f=$this->fixture('en','draft','Status'); $this->check('status-baseline-draft',($this->inspect($f['id'],'status-before')['status']??'')==='draft',[]);
        $p=$this->plan('insight-update',['post_id'=>$f['id'],'changes'=>['status'=>'publish'],'reason'=>'Final v1 Insight status breadth'],'status-plan'); $this->check('status-preview-no-mutation',($this->inspect($f['id'],'status-preview')['status']??'')==='draft',[]);
        $op=$this->apply($p,'status-apply'); $this->verify($op,true,'status-verify'); $this->check('status-published',($this->inspect($f['id'],'status-after')['status']??'')==='publish',[]); $this->rollback($op,'status-rollback'); $this->check('status-baseline-restored',($this->inspect($f['id'],'status-restored')['status']??'')==='draft',[]); $this->cleanup($f,'status-fixture-cleanup');
    }
    private function fixture(string $lang,string $status,string $purpose): array {
        $slug='m8-v1-'.$this->slice.'-'.$lang.'-'.gmdate('YmdHis').'-'.bin2hex(random_bytes(3)); $p=$this->plan('insight-create',['data'=>['title'=>'Temporary M8 '.$purpose.' Insight — reversible production fixture','slug'=>$slug,'excerpt'=>'Temporary production acceptance fixture. Not research content and not an academic claim.','content'=>'<p>Temporary production acceptance fixture used only to verify bounded Research Manager editorial behavior. Not research content and not an academic claim.</p>','language'=>$lang,'insight_type'=>'research_note','status'=>$status],'reason'=>'Final v1 reversible fixture for Insight '.$this->slice],'fixture-'.$lang.'-plan');
        $op=$this->apply($p,'fixture-'.$lang.'-apply'); $this->verify($op,true,'fixture-'.$lang.'-verify'); $d=$this->last('fixture-'.$lang.'-apply'); $id=(int)($d['target']['post_id']??$d['result']['post_id']??0); if($id<=0)throw new RuntimeException('Fixture Apply missing post_id.'); $i=$this->inspect($id,'fixture-'.$lang.'-inspect'); $this->check('fixture-'.$lang.'-managed',($i['slug']??'')===$slug&&($i['language']??'')===$lang,['post_id'=>$id]); return ['id'=>$id,'op'=>$op,'lang'=>$lang,'slug'=>$slug];
    }
    private function cleanup(array $f,string $label): void { $this->rollback($f['op'],$label); $inv=$this->data($this->req('GET','/insights?language='.rawurlencode($f['lang']),null,[200],$label.'-inventory')); $found=false; foreach((array)($inv['items']??[]) as $x)if(is_array($x)&&((int)($x['post_id']??0)===$f['id']||($x['slug']??'')===$f['slug']))$found=true; $this->check($label.'-absent',!$found,['post_id'=>$f['id'],'slug'=>$f['slug']]); }
    private function plan(string $op,array $payload,string $label): string { $d=$this->data($this->req('POST','/operations/plan',['operation'=>$op,'payload'=>$payload],[200],$label)); $id=(string)($d['plan_id']??''); $this->id($id,$label.' plan_id'); $this->check($label.'-apply-allowed',!empty($d['apply_allowed']),['plan'=>$d]); return $id; }
    private function apply(string $plan,string $label): string { $d=$this->data($this->req('POST','/plans/'.rawurlencode($plan).'/apply',['confirm'=>true],[200],$label)); $op=(string)($d['operation_id']??''); $this->id($op,$label.' operation_id'); $this->check($label.'-verified-result',!empty($d['result']['verified']),['apply'=>$d]); $this->track($op,'/operations/'.rawurlencode($op).'/rollback'); return $op; }
    private function verify(string $op,bool $rendered,string $label): void { $d=$this->data($this->req('POST','/operations/'.rawurlencode($op).'/verify',['rendered'=>$rendered],[200],$label)); $this->check($label.'-status',($d['status']??'')==='verified',['verify'=>$d]); if(isset($d['stored_verification']))$this->check($label.'-stored',!empty($d['stored_verification']['verified']),['stored'=>$d['stored_verification']]); if($rendered&&isset($d['rendered_verification']))$this->check($label.'-rendered',!empty($d['rendered_verification']['verified'])||!empty($d['rendered_verification']['not_applicable']),['rendered'=>$d['rendered_verification']]); }
    private function rollback(string $op,string $label): void { foreach($this->rollbacks as &$r)if($r['op']===$op&&!$r['done']){$d=$this->data($this->req('POST',$r['route'],['confirm'=>true],[200],$label)); $s=(string)($d['status']??''); $this->check($label.'-status',$s===''||in_array($s,['rolled-back','rolled_back'],true),['response'=>$d]); $r['done']=true; return;} unset($r); throw new RuntimeException('Untracked rollback '.$op); }
    private function track(string $op,string $route): void { $this->rollbacks[]=['op'=>$op,'route'=>$route,'done'=>false]; }
    private function inspect(int $id,string $label): array { return $this->data($this->req('GET','/insights/'.$id,null,[200],$label)); }
    private function line(): array { $d=$this->data($this->req('GET','/research-lines',null,[200],'relation-line-inventory')); foreach((array)($d['items']??[]) as $x)if(is_array($x)&&($x['language']??'')==='en'&&($x['evidence_status']??'')==='verified'&&($x['research_status']??'')==='active')return $x; return []; }
    private function state(array $x): array { $o=[]; foreach(['post_id','title','slug','excerpt','content','language','insight_type','status','scheduled_at','line_ids'] as $k)$o[$k]=$x[$k]??null; if(is_array($o['line_ids']))$o['line_ids']=array_values(array_map('intval',$o['line_ids'])); return $o; }
    private function req(string $m,string $rel,?array $body,array $expected,string $label): array {
        $rid='m8-insight-breadth-'.preg_replace('/[^A-Za-z0-9._:-]/','-',$label).'-'.time().'-'.bin2hex(random_bytes(4)); $h=['Accept: application/json','Authorization: Bearer '.$this->token,'X-Research-Manager-Request-Id: '.$rid,'X-Research-Manager-Nonce: '.bin2hex(random_bytes(16)),'X-Research-Manager-Timestamp: '.time()]; $payload=''; if($body!==null){$h[]='Content-Type: application/json';$payload=(string)json_encode($body,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);} $c=curl_init($this->base.self::API.$rel); if($c===false)throw new RuntimeException('Unable to initialize cURL.'); curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>strtoupper($m),CURLOPT_HTTPHEADER=>$h,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>45,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_USERAGENT=>'Eduardo-Research-M8-Insight-Breadth/1.0']); if($body!==null)curl_setopt($c,CURLOPT_POSTFIELDS,$payload); $raw=curl_exec($c); if($raw===false){$e=curl_error($c);curl_close($c);throw new RuntimeException('Request failed: '.$e);} $status=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE); curl_close($c); try{$d=json_decode((string)$raw,true,512,JSON_THROW_ON_ERROR);}catch(Throwable){$d=['raw_non_json'=>substr((string)$raw,0,1000)];} if(!is_array($d))$d=['value'=>$d]; $this->evidence['requests'][]=['label'=>$label,'method'=>strtoupper($m),'route'=>self::API.$rel,'request_id'=>$rid,'http_status'=>$status,'response'=>$this->clean($d)]; if(!in_array($status,$expected,true))throw new RuntimeException($label.' returned HTTP '.$status.' (expected '.implode('/',$expected).')'.(!empty($d['code'])?': '.$d['code']:'')); return $d;
    }
    private function emergency(): void { for($i=count($this->rollbacks)-1;$i>=0;--$i)if(!$this->rollbacks[$i]['done'])try{$this->req('POST',$this->rollbacks[$i]['route'],['confirm'=>true],[200],'emergency-rollback-'.$i);$this->rollbacks[$i]['done']=true;$this->evidence['emergency_rollbacks'][]=['op'=>$this->rollbacks[$i]['op'],'success'=>true];}catch(Throwable $e){$this->evidence['emergency_rollbacks'][]=['op'=>$this->rollbacks[$i]['op'],'success'=>false,'error'=>$e->getMessage()];} }
    private function finish(bool $pass,string $msg): int { $this->evidence['result']=$pass?'pass':'fail';$this->evidence['finished_at']=gmdate(DATE_ATOM);$this->write();fwrite($pass?STDOUT:STDERR,$msg."\nEvidence: ".$this->evidencePath."\n");return $pass?0:1; }
    private function validate(): void { if(!str_starts_with($this->base,'https://'))throw new RuntimeException('ERM_BASE_URL must be HTTPS.'); if(!str_starts_with($this->token,'ermt1_'))throw new RuntimeException('ERM_TOKEN must be an independent temporary credential (ermt1_).'); if(!in_array($this->slice,self::SLICES,true))throw new RuntimeException('--slice must be one of: '.implode(', ',self::SLICES)); }
    private function check(string $id,bool $ok,array $details): void { $this->evidence['checks'][]=['id'=>$id,'passes'=>$ok,'details'=>$this->clean($details)]; if(!$ok)throw new RuntimeException('Acceptance check failed: '.$id); }
    private function id(string $v,string $name): void { if(!preg_match('/^[A-Za-z0-9._:-]+$/',$v))throw new RuntimeException('Invalid '.$name.' returned by Manager.'); }
    private function data(array $r): array { return is_array($r['data']??null)?$r['data']:[]; }
    private function last(string $label): array { for($i=count($this->evidence['requests'])-1;$i>=0;--$i){$r=$this->evidence['requests'][$i];if(($r['label']??'')===$label)return is_array($r['response']['data']??null)?$r['response']['data']:[];}return[]; }
    private function clean(mixed $v): mixed { if(is_array($v)){foreach($v as $k=>$x){if(in_array(strtolower((string)$k),['token','token_hash','authorization','password','secret'],true))$v[$k]='[redacted]';else$v[$k]=$this->clean($x);}return$v;} if(is_string($v)&&(str_contains($v,'ermt1_')||str_contains($v,'erm1_')))return'[redacted]'; return$v; }
    private function write(): void { $raw=(string)json_encode($this->clean($this->evidence),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR).PHP_EOL; if(str_contains($raw,'ermt1_')||str_contains($raw,'erm1_'))throw new RuntimeException('Refusing to write bearer-like material.'); $dir=dirname($this->evidencePath); if(!is_dir($dir))mkdir($dir,0700,true); file_put_contents($this->evidencePath,$raw,LOCK_EX); @chmod($this->evidencePath,0600); }
    private function arg(array $argv,string $p): string { foreach($argv as $a)if(str_starts_with((string)$a,$p))return trim(substr((string)$a,strlen($p))); return ''; }
}
$args=$argv; array_shift($args); exit((new M8InsightBreadthAcceptance($args))->run());
